Section BbeSegs.
Context {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LLU16} {P16 : V2Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).
#[local] Notation w8 x := (word_to_le_bytes 8 x) (only parsing).

Definition FRB (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) (fr : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 8)) (w8 ret))
    (Z_to_bv 64 (s - 16)) (w8 (getr regs 8)))
    (Z_to_bv 64 (s - 24)) (w8 (getr regs 9)))
    (Z_to_bv 64 (s - 32)) (w8 (reg_get fr 8)))
    (Z_to_bv 64 (s - 40)) (w8 (reg_get fr 9)).
Definition frameb (s : Z) (ret : word) (r0 : bvmap 5 word) (fr : bvmap 5 word) : list (Z * word) :=
  [((s - 8)%Z, ret); ((s - 16)%Z, getr r0 8); ((s - 24)%Z, getr r0 9); ((s - 32)%Z, reg_get fr 8); ((s - 40)%Z, reg_get fr 9)].
