Section Segs.
Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma bb_A : forall fr cs regs m (s pixs : Z) (v : pixv) (ret : word),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (pixs + 64 <= s - 64)%Z ->
    (pixs mod 8 = 0)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixs -> reg_get fr 10 = L10 -> reg_get fr 11 = L1 ->
    exists regs',
      msteps SEGS (@mkst (mkFP fr cs) regs (0x3b3e4 : word) m rom)
                  (@mkst (mkFP (bvmap_set 9 L10 (bvmap_set 8 L1 fr)) cs) regs' (0x3b410 : word) (FRB m s ret regs fr) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 8 = Z_to_bv 64 pixs /\ getr regs' 10 = Z_to_bv 64 (p_d v)
      /\ regs_agree (fun x => In x [1; 2; 8; 10; 11]%list) regs regs'.
Proof.
    intros fr cs regs m s pixs v ret Hs Hs64 Hp1 PX Hps ALp SOK H2 H1 H10 Hfa0 Hfa1.
    pose proof PX as (Hp0 & Hp64 & WF & _).
    pose proof (wf_d _ WF) as Hdr.
    eexists; split.
    - zv F_3b3e4 D_3b3e4 (Z_to_bv 64 (s - 64)).
      stepST F_3b3e8 D_3b3e8 (Z_to_bv 64 (s - 8)) ret ltac:(sok_in SOK).
      stepST F_3b3ec D_3b3ec (Z_to_bv 64 (s - 16)) (getr regs 8) ltac:(sok_in SOK).
      stepST F_3b3f0 D_3b3f0 (Z_to_bv 64 (s - 24)) (getr regs 9) ltac:(sok_in SOK).
      chain_step; [ reflexivity | eapply fp_step_fsd with (a := Z_to_bv 64 (s - 32)); [exact F_3b3f4 | reflexivity | exact D_3b3f4 | gres; imm_norm; addr_tac | sok_in SOK] | step_simpl ]; fpn.
      chain_step; [ reflexivity | eapply fp_step_fsd with (a := Z_to_bv 64 (s - 40)); [exact F_3b3f8 | reflexivity | exact D_3b3f8 | gres; imm_norm; addr_tac | sok_in SOK] | step_simpl ]; fpn.
      stepb_ft F_3b3fc D_3b3fc ltac:(condZ).
      fsgnj F_3b400 D_3b400. rewrite Hfa1, sgnj_L1.
      fsgnj F_3b404 D_3b404. rewrite Hfa0, sgnj_L10.
      sn F_3b408 D_3b408.
      sn F_3b40c D_3b40c.
      stepb_ft F_1a8cc D_1a8cc ltac:(condZ).
      guard8 F_1a8d0 D_1a8d0 ALp.
      stepb_ft F_1a8d4 D_1a8d4 ltac:(condZ).
      stepLD F_1a8d8 D_1a8d8 (Z_to_le_bytes 4 (p_d v)) (Z_to_bv 64 (p_d v))
        ltac:(addr_norm; repeat rdn_peel1; exact (PIX_rd_d SEGS _ _ _ PX)) ltac:(apply lez4; lia).
      rewrite (v_lw_small (p_d v)) by lia.
      stepret F_1a8dc D_1a8dc (0x3b410 : word) ltac:(bveq).
      apply mst_refl.
    - repeat split; try solve_regs_agree; gres; pin; try reflexivity.
Qed.

  (* [comment removed for export] *)
  Lemma bb_B : forall (fx : FPState) regs m (s pixs : Z) (v : pixv),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (p_d v = 8 \/ p_d v = 32)%Z ->
    (pixs mod 8 = 0)%Z ->
    getr regs 8 = Z_to_bv 64 pixs -> getr regs 10 = Z_to_bv 64 (p_d v) ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x3b410 : word) m rom) (@mkst fx regs' (0x3b428 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 (p_cmap v) /\ getr regs' 1 = Z_to_bv 64 0x3b428
      /\ regs_agree (fun x => In x [1; 10; 11]%list) regs regs'.
Proof.
    intros fx regs m s pixs v Hs Hs64 Hp1 PX Hd ALp H8 H10.
    pose proof PX as (Hp0 & Hp64 & WF & _).
    pose proof (wf_cmap _ WF) as Hcr.
    destruct Hd as [D8 | D32]; eexists; split.
    - zv F_3b410 D_3b410 (Z_to_bv 64 8).
