      rewrite exf_extract64; unfold le_bytes_to_word; rewrite bytes_le_to_Z_8, zbv_self.
      chain_step; [ reflexivity | eapply fp_step_fld with (a := Z_to_bv 64 (s - 40)) (bs := word_to_le_bytes 8 (reg_get fr0 9)); [exact F_3b594 | reflexivity | exact D_3b594 | gres; imm_norm; addr_tac | exact C5] | step_simpl ]; fpn.
      rewrite exf_extract64; unfold le_bytes_to_word; rewrite bytes_le_to_Z_8, zbv_self.
      zv F_3b598 D_3b598 (Z_to_bv 64 s).
      sn F_3b59c D_3b59c.
      apply mst_refl.
    - repeat split; gres; pin; try reflexivity; try solve_regs_agree.
      intros x Hx; cbn in Hx; repeat destruct Hx as [<- | Hx]; first [ contradiction | gres; pin; reflexivity ].
