  (* [comment removed for export] *)
  Lemma bb_C : forall fr cs regs m,
    frm_zero cs -> reg_get fr 9 = L10 -> reg_get fr 8 = L1 -> getr regs 10 = Z_to_bv 64 0 ->
    rdn SEGS m (Z_to_bv 64 0x127ac) 4 = Some (Z_to_le_bytes 4 0xcf000001) ->
    exists fr' cs' regs',
      msteps SEGS (@mkst (mkFP fr cs) regs (0x3b428 : word) m rom) (@mkst (mkFP fr' cs') regs' (0x390ac : word) m rom)
      /\ frm_zero cs' /\ reg_get fr' 10 = L10 /\ reg_get fr' 11 = L1 /\ reg_get fr' 8 = L1 /\ reg_get fr' 9 = L10
      /\ (forall r : reg, r <> 10%bv -> r <> 11%bv -> r <> 14%bv -> r <> 15%bv -> reg_get fr' r = reg_get fr r)
      /\ getr regs' 10 = Z_to_bv 64 20 /\ getr regs' 11 = Z_to_bv 64 20 /\ getr regs' 1 = Z_to_bv 64 0x3b4f4
      /\ regs_agree (fun x => In x [1; 10; 11]%list) regs regs'.
Proof.
    intros fr cs regs m Hz F9 F8 H10 RC.
    assert (R9 : fpv_read fr FMT_S 9 = bv_unsigned (unbox_s L10)) by (unfold fpv_read; rewrite F9; reflexivity).
    assert (R8 : fpv_read fr FMT_S 8 = bv_unsigned (unbox_s L1)) by (unfold fpv_read; rewrite F8; reflexivity).
    assert (KL : bv_extract 0 32 (le_bytes_to_word (Z_to_le_bytes 4 0xcf000001)) = Z_to_bv 32 0xcf000001) by (apply bv_eq; vm_compute; reflexivity).
    eexists _, _, _. split.
    - stepb_tk F_3b428 D_3b428 ltac:(condZ).
      fmvwx F_3b4a4 D_3b4a4.
      fcmp F_3b4a8 D_3b4a8. rewrite R9, ?getr_zero.
      stepb_ft F_3b4ac D_3b4ac ltac:(cond_compute).
      fcmp F_3b4b0 D_3b4b0. rewrite R8, ?getr_zero.
      stepb_ft F_3b4b4 D_3b4b4 ltac:(cond_compute).
      sn F_3b4b8 D_3b4b8.
      chain_step; [ reflexivity | eapply fp_step_flw with (a := Z_to_bv 64 0x127ac) (bs := Z_to_le_bytes 4 0xcf000001); [exact F_3b4bc | reflexivity | exact D_3b4bc | gres; imm_norm; addr_tac | exact RC] | step_simpl ]; fpn.
      rewrite KL.
      fari F_3b4c0 D_3b4c0 Hz. rewrite R9.
      fcmp F_3b4c4 D_3b4c4.
      stepb_ft F_3b4c8 D_3b4c8 ltac:(cond_compute).
      sn F_3b4cc D_3b4cc.
      fmvwx F_3b4d0 D_3b4d0.
      fcmp F_3b4d4 D_3b4d4.
      stepb_ft F_3b4d8 D_3b4d8 ltac:(cond_compute).
      fcvt_ws F_3b4dc D_3b4dc Hz.
      sn F_3b4e0 D_3b4e0.
      fmvwx F_3b4e4 D_3b4e4.
      sn F_3b4e8 D_3b4e8.
      fsgnj F_3b4ec D_3b4ec. rewrite F9, sgnj_L10.
      sn F_3b4f0 D_3b4f0.
      apply mst_refl.
    - repeat split.
      + repeat apply fpv_frm_acc; exact Hz.
      + rewrite fpv_get_same; reflexivity.
      + rewrite fpv_get_other, fpv_get_same by reg_neq_tac; gres; pin; apply bv_eq; vm_compute; reflexivity.
      + rewrite ?fpv_get_other by reg_neq_tac; exact F8.
      + rewrite ?fpv_get_other by reg_neq_tac; exact F9.
      + intros r N10 N11 N14 N15. rewrite ?fpv_get_other by assumption. reflexivity.
      + gres; pin. rewrite <- halfwidth_20, fpv_unbox_box. reflexivity.
      + gres; pin. rewrite <- halfwidth_20, fpv_unbox_box. reflexivity.
      + gres; pin; reflexivity.
      + solve_regs_agree.
Qed.

